-- ==============================================================================
-- 🌊 AquaBuddy 국립해양조사원 192개 전체 해양 관측 스팟 마스터 SQL 스크립트
-- ==============================================================================

-- 1. ocean_weather_cache 테이블 생성
CREATE TABLE IF NOT EXISTS public.ocean_weather_cache (
    spot_id VARCHAR(100) PRIMARY KEY,
    spot_name VARCHAR(100) NOT NULL,
    region_cat VARCHAR(50),
    lat NUMERIC(10, 6),
    lng NUMERIC(10, 6),
    scuba_index_grade VARCHAR(50) DEFAULT '매우좋음',
    scuba_point_name VARCHAR(100),
    tide_forecast_json JSONB DEFAULT '[]'::jsonb,
    high_tide VARCHAR(100) DEFAULT '07:37 (553cm)',
    low_tide VARCHAR(100) DEFAULT '13:40 (120cm)',
    water_temp VARCHAR(30) DEFAULT '24.5°C',
    wave_height VARCHAR(30) DEFAULT '0.2m',
    wind_speed VARCHAR(30) DEFAULT '1.0 m/s',
    air_temp VARCHAR(30) DEFAULT '26.4°C',
    is_live BOOLEAN DEFAULT true,
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- 2. RLS (Row Level Security) 읽기/쓰기 보안 정책 설정
ALTER TABLE public.ocean_weather_cache ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Allow public read ocean_weather_cache" ON public.ocean_weather_cache;
CREATE POLICY "Allow public read ocean_weather_cache" ON public.ocean_weather_cache FOR SELECT USING (true);
DROP POLICY IF EXISTS "Allow public insert/update ocean_weather_cache" ON public.ocean_weather_cache;
CREATE POLICY "Allow public insert/update ocean_weather_cache" ON public.ocean_weather_cache FOR ALL USING (true) WITH CHECK (true);

-- 3. 192개 전체 해양 관측 스팟 마스터 데이터 초기화 (Upsert)
ON CONFLICT (spot_id) DO UPDATE SET
spot_name = EXCLUDED.spot_name,
region_cat = EXCLUDED.region_cat,
lat = EXCLUDED.lat,
lng = EXCLUDED.lng,
updated_at = NOW();